/**
 * Shared MCP JSON-RPC stdio loop (shipped with thetowersdk; reused by monorepo tower-mcp).
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    runStdioMcp, isDirectRun
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export function runStdioMcp({ name, version, instructions, tools }) {
  const send = msg => process.stdout.write(`${JSON.stringify(msg)}\n`)
  const own = (record, key) => Object.prototype.hasOwnProperty.call(record, key) ? record[key] : undefined
  const fail = (id, code, message) => send({ jsonrpc: '2.0', id, error: { code, message } })

  const handlers = {
    initialize: () => ({
      protocolVersion: '2024-11-05',
      capabilities: { tools: {} },
      serverInfo: { name, version },
      instructions,
    }),
    'tools/list': () => ({
      // Compact descriptions so large tool sets fit Cursor's catalog (~40–100 tools).
      tools: Object.entries(tools).map(([toolName, t]) => {
        const desc = String(t.description ?? '')
        return {
          name: toolName,
          description: desc.length > 180 ? `${desc.slice(0, 177)}...` : desc,
          inputSchema: t.inputSchema ?? { type: 'object', properties: {} },
        }
      }),
    }),
    'tools/call': async ({ name: toolName, arguments: args }) => {
      const tool = own(tools, toolName)
      if (!tool) {
        return { isError: true, content: [{ type: 'text', text: `unknown tool: ${toolName}` }] }
      }
      try {
        const result = await tool.run(args ?? {})
        return { content: [{ type: 'text', text: JSON.stringify(result, null, 2) }] }
      } catch (error) {
        return {
          isError: true,
          content: [{ type: 'text', text: `${toolName} failed: ${error.message}` }],
        }
      }
    },
  }

  let buffer = ''
  // Node's decoder retains incomplete UTF-8 sequences between pipe chunks.
  process.stdin.setEncoding('utf8')
  process.stdin.on('data', chunk => {
    buffer += chunk
    let newline
    while ((newline = buffer.indexOf('\n')) !== -1) {
      const line = buffer.slice(0, newline).trim()
      buffer = buffer.slice(newline + 1)
      if (!line) continue

      let request
      try {
        request = JSON.parse(line)
      } catch {
        fail(null, -32700, 'Parse error')
        continue
      }

      if (!request || typeof request !== 'object' || Array.isArray(request)
        || request.jsonrpc !== '2.0' || typeof request.method !== 'string'
        || (request.id !== undefined && request.id !== null && typeof request.id !== 'string' && typeof request.id !== 'number')) {
        fail(null, -32600, 'Invalid Request')
        continue
      }
      const hasId = Object.prototype.hasOwnProperty.call(request, 'id')
      const handler = own(handlers, request.method)
      if (!handler) {
        if (hasId) {
          send({
            jsonrpc: '2.0',
            id: request.id,
            error: { code: -32601, message: `unknown method: ${request.method}` },
          })
        }
        continue
      }
      if (request.params !== undefined && (!request.params || typeof request.params !== 'object' || Array.isArray(request.params))) {
        if (hasId) fail(request.id, -32602, 'Invalid params')
        continue
      }
      Promise.resolve()
        .then(() => handler(request.params ?? {}))
        .then(result => { if (hasId) send({ jsonrpc: '2.0', id: request.id, result }) })
        .catch(error => { if (hasId) fail(request.id, -32603, error instanceof Error ? error.message : String(error)) })
    }
  })
}

export function isDirectRun(importMetaUrl) {
  const entry = process.argv[1]
  if (!entry) return false
  try {
    return normalizePath(realPathOf(entry)) === normalizePath(realPathOf(fileURLToPath(importMetaUrl)))
  } catch {
    return false
  }
}

/**
 * The path with its symlinks followed.
 *
 * `process.argv[1]` is the path as it was typed, and `import.meta.url` is the file Node actually
 * loaded. Through `node_modules/.bin` -- which is how `npx thetowersdk-mcp` runs -- or a pnpm
 * install, those differ, and comparing them unresolved made the server conclude it had been
 * imported and exit without a word.
 */
function realPathOf(file) {
  const resolved = path.resolve(file)
  try {
    return fs.realpathSync(resolved)
  } catch {
    return resolved
  }
}

function normalizePath(p) {
  return String(p).replace(/\\/g, '/').toLowerCase()
}
